    "CREATE TABLE configuration_activations (\n        activation_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        candidate_id TEXT NOT NULL REFERENCES learning_candidates(candidate_id),\n        decision_id TEXT NOT NULL REFERENCES learning_candidate_decisions(decision_id),\n        operation_id TEXT NOT NULL REFERENCES promotion_operations(operation_id),\n        target TEXT NOT NULL CHECK (length(target) BETWEEN 1 AND 64),\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace', 'session', 'task')),\n        path TEXT NOT NULL CHECK (length(path) BETWEEN 1 AND 256),\n        operation TEXT NOT NULL CHECK (operation IN ('set', 'append', 'replace', 'remove')),\n        applied_revision INTEGER NOT NULL CHECK (applied_revision >= 1),\n        before_digest TEXT CHECK (before_digest IS NULL OR length(before_digest) = 64),\n        after_digest TEXT NOT NULL CHECK (length(after_digest) = 64),\n        value_digest TEXT NOT NULL CHECK (length(value_digest) = 64),\n        inverse_command_json TEXT NOT NULL CHECK (\n            length(inverse_command_json) BETWEEN 2 AND 8192\n        ),\n        inverse_command_digest TEXT NOT NULL CHECK (length(inverse_command_digest) = 64),\n        supersedes_activation_id TEXT REFERENCES configuration_activations(activation_id),\n        reverses_activation_id TEXT REFERENCES configuration_activations(activation_id),\n        status TEXT NOT NULL CHECK (status IN ('active', 'reversed', 'superseded')),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        CHECK (updated_at_unix >= created_at_unix)\n    )",
    'CREATE TABLE context_checkpoints (\n        checkpoint_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        task_run_id TEXT REFERENCES task_runs(task_run_id),\n        source_agent_run_id TEXT REFERENCES agent_runs(agent_run_id),\n        codec TEXT NOT NULL,\n        method_version TEXT NOT NULL,\n        source_start_record_id TEXT,\n        source_start_position INTEGER NOT NULL CHECK (source_start_position >= 0),\n        source_end_record_id TEXT NOT NULL,\n        source_end_position INTEGER NOT NULL CHECK (source_end_position > source_start_position),\n        retained_record_ids_json TEXT NOT NULL,\n        sections_json TEXT NOT NULL,\n        omitted_sections_json TEXT NOT NULL,\n        artifact_refs_json TEXT NOT NULL,\n        input_bytes INTEGER NOT NULL CHECK (input_bytes >= 0),\n        output_bytes INTEGER NOT NULL CHECK (output_bytes >= 0),\n        request_estimate_chars INTEGER NOT NULL CHECK (request_estimate_chars >= 0),\n        created_at_unix INTEGER NOT NULL,\n        CHECK (task_run_id IS NULL OR session_id IS NOT NULL)\n    )',
    "CREATE TABLE conversation_records (\n        record_id TEXT PRIMARY KEY,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        conversation_position INTEGER NOT NULL CHECK (conversation_position >= 1),\n        kind TEXT NOT NULL CHECK (kind IN ('message', 'terminal')),\n        payload_json TEXT NOT NULL,\n        payload_bytes INTEGER NOT NULL CHECK (payload_bytes >= 0),\n        UNIQUE (session_id, conversation_position)\n    )",
    "CREATE TABLE learning_candidate_decisions (\n        decision_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        candidate_id TEXT NOT NULL REFERENCES learning_candidates(candidate_id),\n        kind TEXT NOT NULL CHECK (kind IN (\n            'accept', 'edit_and_accept', 'reject', 'reject_and_suppress',\n            'expire', 'supersede'\n        )),\n        actor TEXT NOT NULL CHECK (actor IN ('user', 'policy')),\n        original_proposal_digest TEXT NOT NULL CHECK (length(original_proposal_digest) = 64),\n        final_proposal_json TEXT,\n        final_proposal_bytes INTEGER CHECK (\n            final_proposal_bytes IS NULL OR final_proposal_bytes BETWEEN 1 AND 8192\n        ),\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace', 'session', 'task')),\n        conflict_resolution TEXT NOT NULL CHECK (conflict_resolution IN (\n            'none', 'confirm', 'replace', 'merge', 're_enable', 'resolve_dispute'\n        )),\n        command_id TEXT NOT NULL,\n        created_at_unix INTEGER NOT NULL,\n        UNIQUE (workspace_id, command_id),\n        CHECK ((final_proposal_json IS NULL) = (final_proposal_bytes IS NULL)),\n        CHECK ((kind = 'edit_and_accept') = (final_proposal_json IS NOT NULL)),\n        CHECK (final_proposal_json IS NULL OR length(final_proposal_json) BETWEEN 2 AND 8192)\n    )",
    'CREATE TABLE learning_candidate_evidence (\n        workspace_id TEXT NOT NULL,\n        candidate_id TEXT NOT NULL REFERENCES learning_candidates(candidate_id),\n        evidence_id TEXT NOT NULL REFERENCES learning_evidence(evidence_id),\n        PRIMARY KEY (candidate_id, evidence_id)\n    )',
    "CREATE TABLE learning_candidates (\n        candidate_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        origin_review_id TEXT NOT NULL REFERENCES learning_reviews(review_id),\n        candidate_type TEXT NOT NULL CHECK (candidate_type IN (\n            'preference', 'profile', 'project_knowledge', 'skill_candidate',\n            'workflow_feedback', 'orchestration_policy_candidate'\n        )),\n        operation TEXT NOT NULL CHECK (operation IN ('set', 'append', 'replace', 'remove')),\n        semantic_key TEXT NOT NULL,\n        proposed_scope TEXT NOT NULL CHECK (\n            proposed_scope IN ('global', 'workspace', 'session', 'task')\n        ),\n        proposed_payload_json TEXT NOT NULL,\n        proposed_payload_bytes INTEGER NOT NULL CHECK (\n            proposed_payload_bytes BETWEEN 1 AND 8192\n        ),\n        fingerprint TEXT NOT NULL CHECK (length(fingerprint) = 64),\n        status TEXT NOT NULL CHECK (status IN (\n            'proposed', 'promoting', 'accepted', 'edited_and_accepted',\n            'rejected', 'expired', 'superseded'\n        )),\n        evidence_ids_json TEXT NOT NULL,\n        confidence_band TEXT NOT NULL CHECK (confidence_band IN ('low', 'medium', 'high')),\n        confidence_basis_json TEXT NOT NULL,\n        sensitivity TEXT NOT NULL CHECK (\n            sensitivity IN ('normal', 'personal', 'sensitive', 'prohibited')\n        ),\n        expected_target_revision INTEGER CHECK (expected_target_revision IS NULL OR expected_target_revision >= 1),\n        duplicate_of_id TEXT REFERENCES learning_candidates(candidate_id),\n        supersedes_id TEXT REFERENCES learning_candidates(candidate_id),\n        conflict_refs_json TEXT NOT NULL,\n        expires_at_unix INTEGER NOT NULL,\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        resolved_at_unix INTEGER,\n        resolved_by TEXT CHECK (resolved_by IS NULL OR resolved_by IN ('user', 'policy')),\n        rejection_reason TEXT,\n        CHECK (resolved_at_unix IS NULL OR resolved_at_unix >= created_at_unix),\n        CHECK (status IN ('proposed', 'promoting') OR resolved_at_unix IS NOT NULL),\n        CHECK (status IN ('proposed', 'promoting') OR resolved_by IS NOT NULL)\n    )",
    "CREATE TABLE learning_evidence (\n        evidence_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        origin_review_id TEXT NOT NULL REFERENCES learning_reviews(review_id),\n        task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        source_kind TEXT NOT NULL CHECK (source_kind IN (\n            'user_turn', 'task_transition', 'task_outcome', 'artifact',\n            'tool_execution', 'configuration', 'candidate_decision', 'system'\n        )),\n        source_id TEXT NOT NULL,\n        source_pointer TEXT NOT NULL DEFAULT '',\n        actor TEXT NOT NULL CHECK (actor IN ('user', 'assistant', 'tool', 'system')),\n        authority TEXT NOT NULL CHECK (authority IN (\n            'user_explicit_persistent', 'user_correction', 'user_acceptance',\n            'configuration_change', 'deterministic_task_fact',\n            'deterministic_artifact_fact', 'behavioral_signal',\n            'untrusted_external_content'\n        )),\n        explicitness TEXT NOT NULL CHECK (\n            explicitness IN ('explicit', 'behavioral', 'inferred')\n        ),\n        polarity TEXT NOT NULL CHECK (polarity IN ('positive', 'negative', 'neutral')),\n        scope_hint TEXT CHECK (\n            scope_hint IS NULL OR scope_hint IN ('global', 'workspace', 'session', 'task')\n        ),\n        excerpt_redacted TEXT,\n        excerpt_bytes INTEGER NOT NULL CHECK (excerpt_bytes BETWEEN 0 AND 2048),\n        content_digest TEXT NOT NULL CHECK (length(content_digest) = 64),\n        safety_rejection_code TEXT CHECK (\n            safety_rejection_code IS NULL OR safety_rejection_code IN (\n                'secret_material', 'prohibited_personal_data',\n                'hidden_unicode_control', 'capability_authorization',\n                'prompt_injection'\n            )\n        ),\n        observed_at_unix INTEGER NOT NULL,\n        created_at_unix INTEGER NOT NULL,\n        UNIQUE (workspace_id, source_kind, source_id, source_pointer),\n        CHECK ((safety_rejection_code IS NULL) OR excerpt_redacted IS NULL),\n        CHECK (excerpt_redacted IS NULL OR length(excerpt_redacted) <= 512)\n    )",
    "CREATE TABLE learning_policies (\n        workspace_id TEXT PRIMARY KEY,\n        mode TEXT NOT NULL CHECK (mode IN ('off', 'review_only')),\n        candidate_ttl_days INTEGER NOT NULL CHECK (candidate_ttl_days BETWEEN 1 AND 365),\n        max_candidates_per_review INTEGER NOT NULL CHECK (\n            max_candidates_per_review BETWEEN 1 AND 3\n        ),\n        max_evidence_per_review INTEGER NOT NULL CHECK (\n            max_evidence_per_review BETWEEN 1 AND 32\n        ),\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        CHECK (updated_at_unix >= created_at_unix)\n    )",
    'CREATE TABLE learning_review_evidence (\n        workspace_id TEXT NOT NULL,\n        review_id TEXT NOT NULL REFERENCES learning_reviews(review_id),\n        evidence_id TEXT NOT NULL REFERENCES learning_evidence(evidence_id),\n        PRIMARY KEY (review_id, evidence_id)\n    )',
    "CREATE TABLE learning_reviews (\n        review_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        task_outcome_id TEXT NOT NULL REFERENCES task_outcomes(outcome_id),\n        review_version INTEGER NOT NULL CHECK (review_version >= 1),\n        trigger TEXT NOT NULL CHECK (trigger IN ('task_accepted', 'explicit_request')),\n        status TEXT NOT NULL CHECK (\n            status IN ('pending', 'running', 'completed', 'failed', 'superseded')\n        ),\n        policy_snapshot_json TEXT NOT NULL,\n        policy_snapshot_bytes INTEGER NOT NULL CHECK (\n            policy_snapshot_bytes BETWEEN 1 AND 8192\n        ),\n        policy_digest TEXT NOT NULL CHECK (length(policy_digest) = 64),\n        reviewer_provider_id TEXT,\n        reviewer_model_id TEXT,\n        reviewer_prompt_version TEXT NOT NULL,\n        reviewer_schema_version TEXT NOT NULL,\n        supersedes_review_id TEXT REFERENCES learning_reviews(review_id),\n        lease_id TEXT UNIQUE,\n        lease_expires_at_unix INTEGER,\n        attempt_count INTEGER NOT NULL CHECK (attempt_count BETWEEN 0 AND 32),\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        started_at_unix INTEGER,\n        completed_at_unix INTEGER,\n        failure_code TEXT CHECK (\n            failure_code IS NULL OR failure_code IN (\n                'provider_unavailable', 'timeout', 'invalid_output',\n                'safety_rejected', 'lease_lost', 'cancelled', 'internal'\n            )\n        ),\n        UNIQUE (workspace_id, task_outcome_id, review_version),\n        CHECK (status != 'running' OR (lease_id IS NOT NULL AND lease_expires_at_unix IS NOT NULL)),\n        CHECK (status != 'failed' OR failure_code IS NOT NULL),\n        CHECK (status = 'failed' OR failure_code IS NULL),\n        CHECK (completed_at_unix IS NULL OR completed_at_unix >= created_at_unix)\n    )",
    "CREATE TABLE learning_suppressions (\n        suppression_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        candidate_type TEXT NOT NULL CHECK (candidate_type IN (\n            'preference', 'profile', 'project_knowledge', 'skill_candidate',\n            'workflow_feedback', 'orchestration_policy_candidate'\n        )),\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace', 'session', 'task')),\n        semantic_key TEXT,\n        fingerprint TEXT CHECK (fingerprint IS NULL OR length(fingerprint) = 64),\n        source_candidate_id TEXT REFERENCES learning_candidates(candidate_id),\n        reason TEXT NOT NULL CHECK (length(reason) BETWEEN 1 AND 256),\n        status TEXT NOT NULL CHECK (status IN ('active', 'disabled', 'expired')),\n        expires_at_unix INTEGER,\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        CHECK (semantic_key IS NOT NULL OR fingerprint IS NOT NULL),\n        CHECK (updated_at_unix >= created_at_unix)\n    )",
    "CREATE TABLE mcp_catalog_revisions (\n        catalog_revision_id TEXT PRIMARY KEY,\n        server_id TEXT NOT NULL,\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace')),\n        scope_id TEXT NOT NULL,\n        revision INTEGER NOT NULL CHECK (revision >= 1),\n        status TEXT NOT NULL CHECK (status IN ('empty', 'ready', 'degraded', 'unavailable')),\n        catalog_digest TEXT NOT NULL CHECK (length(catalog_digest) = 64),\n        handshake_json TEXT,\n        degraded_reason TEXT,\n        created_at_unix INTEGER NOT NULL,\n        UNIQUE (scope, scope_id, server_id, revision),\n        FOREIGN KEY (scope, scope_id, server_id)\n            REFERENCES mcp_servers(scope, scope_id, server_id)\n            ON DELETE CASCADE\n    )",
    "CREATE TABLE mcp_catalog_tools (\n        catalog_revision_id TEXT NOT NULL REFERENCES mcp_catalog_revisions(catalog_revision_id)\n            ON DELETE CASCADE,\n        remote_name TEXT NOT NULL CHECK (length(remote_name) BETWEEN 1 AND 128),\n        local_name TEXT NOT NULL CHECK (length(local_name) BETWEEN 7 AND 64),\n        description TEXT NOT NULL DEFAULT '',\n        input_schema_json TEXT,\n        output_schema_json TEXT,\n        schema_dialect TEXT,\n        input_schema_digest TEXT CHECK (\n            input_schema_digest IS NULL OR length(input_schema_digest) = 64\n        ),\n        output_schema_digest TEXT CHECK (\n            output_schema_digest IS NULL OR length(output_schema_digest) = 64\n        ),\n        annotations_json TEXT NOT NULL CHECK (length(annotations_json) BETWEEN 2 AND 8192),\n        status TEXT NOT NULL\n            CHECK (status IN ('ready', 'invalid_schema', 'unmapped', 'disallowed')),\n        invalid_reason TEXT,\n        effect TEXT CHECK (\n            effect IS NULL OR effect IN ('none', 'session_write', 'persistent_write')\n        ),\n        approval TEXT CHECK (\n            approval IS NULL OR approval IN ('deny', 'require_approval', 'allow')\n        ),\n        mapping_enabled INTEGER CHECK (mapping_enabled IS NULL OR mapping_enabled IN (0, 1)),\n        PRIMARY KEY (catalog_revision_id, remote_name),\n        UNIQUE (catalog_revision_id, local_name),\n        CHECK (input_schema_json IS NULL OR length(input_schema_json) <= 16384),\n        CHECK (output_schema_json IS NULL OR length(output_schema_json) <= 16384)\n    )",
    'CREATE TABLE mcp_result_artifact_links (\n        link_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        tool_execution_id TEXT NOT NULL REFERENCES tool_executions(tool_execution_id),\n        artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),\n        role TEXT NOT NULL CHECK (length(role) BETWEEN 1 AND 64),\n        created_at_unix INTEGER NOT NULL,\n        UNIQUE (tool_execution_id, artifact_id, role)\n    )',
    "CREATE TABLE mcp_run_launch_snapshots (\n        launch_snapshot_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        agent_run_id TEXT NOT NULL REFERENCES agent_runs(agent_run_id),\n        server_id TEXT NOT NULL,\n        config_revision INTEGER NOT NULL CHECK (config_revision >= 1),\n        config_digest TEXT NOT NULL CHECK (length(config_digest) = 64),\n        catalog_revision INTEGER NOT NULL CHECK (catalog_revision >= 1),\n        catalog_digest TEXT NOT NULL CHECK (length(catalog_digest) = 64),\n        transport TEXT NOT NULL CHECK (transport = 'stdio'),\n        argv_digest TEXT NOT NULL CHECK (length(argv_digest) = 64),\n        executable_digest TEXT NOT NULL CHECK (length(executable_digest) = 64),\n        cwd_policy TEXT NOT NULL CHECK (cwd_policy IN ('workspace', 'absolute', 'managed')),\n        workspace_visibility TEXT NOT NULL\n            CHECK (workspace_visibility IN ('none', 'read_only', 'read_write')),\n        network_risk INTEGER NOT NULL CHECK (network_risk IN (0, 1)),\n        credential_risk INTEGER NOT NULL CHECK (credential_risk IN (0, 1)),\n        outside_workspace_risk INTEGER NOT NULL CHECK (outside_workspace_risk IN (0, 1)),\n        allowlisted_remote_tools_json TEXT NOT NULL,\n        toolset_digest TEXT NOT NULL CHECK (length(toolset_digest) = 64),\n        created_at_unix INTEGER NOT NULL\n    )",
    "CREATE TABLE mcp_run_tool_snapshots (\n        tool_snapshot_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        launch_snapshot_id TEXT NOT NULL REFERENCES mcp_run_launch_snapshots(launch_snapshot_id),\n        agent_run_id TEXT NOT NULL REFERENCES agent_runs(agent_run_id),\n        server_id TEXT NOT NULL,\n        remote_name TEXT NOT NULL,\n        local_name TEXT NOT NULL,\n        schema_dialect TEXT NOT NULL,\n        input_schema_digest TEXT NOT NULL CHECK (length(input_schema_digest) = 64),\n        output_schema_digest TEXT CHECK (\n            output_schema_digest IS NULL OR length(output_schema_digest) = 64\n        ),\n        effect TEXT NOT NULL CHECK (effect IN ('none', 'session_write', 'persistent_write')),\n        approval TEXT NOT NULL CHECK (approval IN ('deny', 'require_approval', 'allow')),\n        catalog_revision INTEGER NOT NULL CHECK (catalog_revision >= 1),\n        recovery_declaration_json TEXT NOT NULL CHECK (length(recovery_declaration_json) <= 16384),\n        created_at_unix INTEGER NOT NULL\n    )",
    "CREATE TABLE mcp_servers (\n        server_id TEXT NOT NULL,\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace')),\n        scope_id TEXT NOT NULL,\n        display_name TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 256),\n        transport TEXT NOT NULL CHECK (transport = 'stdio'),\n        executable TEXT NOT NULL CHECK (length(executable) BETWEEN 1 AND 4096),\n        argv_json TEXT NOT NULL CHECK (length(argv_json) BETWEEN 2 AND 262144),\n        argv_digest TEXT NOT NULL CHECK (length(argv_digest) = 64),\n        executable_kind TEXT NOT NULL CHECK (executable_kind IN ('absolute', 'managed')),\n        cwd_policy TEXT NOT NULL CHECK (cwd_policy IN ('workspace', 'absolute', 'managed')),\n        cwd TEXT,\n        timeout_ms INTEGER NOT NULL CHECK (timeout_ms BETWEEN 100 AND 300000),\n        credential_refs_json TEXT NOT NULL CHECK (length(credential_refs_json) BETWEEN 2 AND 8192),\n        workspace_visibility TEXT NOT NULL\n            CHECK (workspace_visibility IN ('none', 'read_only', 'read_write')),\n        launch_risks_json TEXT NOT NULL CHECK (length(launch_risks_json) BETWEEN 2 AND 4096),\n        enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),\n        tool_policy_json TEXT NOT NULL CHECK (length(tool_policy_json) BETWEEN 2 AND 32768),\n        config_revision INTEGER NOT NULL CHECK (config_revision >= 1),\n        config_digest TEXT NOT NULL CHECK (length(config_digest) = 64),\n        catalog_revision INTEGER,\n        catalog_digest TEXT CHECK (catalog_digest IS NULL OR length(catalog_digest) = 64),\n        catalog_status TEXT NOT NULL\n            CHECK (catalog_status IN ('empty', 'ready', 'degraded', 'unavailable')),\n        degraded_reason TEXT,\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        PRIMARY KEY (scope, scope_id, server_id),\n        CHECK ((scope = 'global' AND scope_id = '')\n               OR (scope = 'workspace' AND scope_id LIKE 'ws_%'))\n    )",
    "CREATE TABLE memory_search_terms (\n        workspace_id TEXT NOT NULL,\n        knowledge_revision_id TEXT NOT NULL\n            REFERENCES project_knowledge_revisions(knowledge_revision_id),\n        token_kind TEXT NOT NULL CHECK (\n            token_kind IN ('word', 'identifier', 'cjk_bigram', 'number', 'path')\n        ),\n        token TEXT NOT NULL CHECK (length(token) BETWEEN 1 AND 128),\n        weight_band TEXT NOT NULL CHECK (weight_band IN ('high', 'medium', 'low')),\n        PRIMARY KEY (workspace_id, knowledge_revision_id, token_kind, token)\n    )",
    "CREATE TABLE memory_selection_items (\n        selection_id TEXT NOT NULL REFERENCES memory_selections(selection_id),\n        workspace_id TEXT NOT NULL,\n        ordinal INTEGER NOT NULL CHECK (ordinal >= 1),\n        record_kind TEXT NOT NULL CHECK (record_kind = 'project_knowledge'),\n        record_id TEXT NOT NULL REFERENCES project_knowledge_heads(knowledge_id),\n        record_revision_id TEXT NOT NULL\n            REFERENCES project_knowledge_revisions(knowledge_revision_id),\n        revision INTEGER NOT NULL CHECK (revision >= 1),\n        reason_json TEXT NOT NULL CHECK (length(reason_json) BETWEEN 2 AND 2048),\n        reason_bytes INTEGER NOT NULL CHECK (reason_bytes BETWEEN 2 AND 2048),\n        estimated_chars INTEGER NOT NULL CHECK (estimated_chars >= 0),\n        rendered_content_digest TEXT NOT NULL CHECK (length(rendered_content_digest) = 64),\n        PRIMARY KEY (selection_id, ordinal),\n        UNIQUE (selection_id, record_revision_id),\n        CHECK (reason_bytes = length(reason_json))\n    )",
    'CREATE TABLE memory_selections (\n        selection_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        query_digest TEXT NOT NULL CHECK (length(query_digest) = 64),\n        source_memory_revision INTEGER NOT NULL CHECK (source_memory_revision >= 0),\n        item_count INTEGER NOT NULL CHECK (item_count BETWEEN 0 AND 12),\n        omitted_count INTEGER NOT NULL CHECK (omitted_count >= 0),\n        rendered_chars INTEGER NOT NULL CHECK (rendered_chars BETWEEN 0 AND 6144),\n        selection_digest TEXT NOT NULL CHECK (length(selection_digest) = 64),\n        created_at_unix INTEGER NOT NULL,\n        UNIQUE (workspace_id, selection_id)\n    )',
    'CREATE TABLE memory_workspace_state (\n        workspace_id TEXT PRIMARY KEY,\n        memory_revision INTEGER NOT NULL DEFAULT 0 CHECK (memory_revision >= 0),\n        row_version INTEGER NOT NULL DEFAULT 1 CHECK (row_version >= 1),\n        updated_at_unix INTEGER NOT NULL\n    )',
    "CREATE TABLE permission_snapshots (\n        permission_snapshot_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        turn_id TEXT NOT NULL REFERENCES turns(turn_id),\n        agent_run_id TEXT NOT NULL UNIQUE REFERENCES agent_runs(agent_run_id),\n        access_scope TEXT NOT NULL CHECK (access_scope IN ('workspace', 'full_access')),\n        approval_mode TEXT NOT NULL CHECK (approval_mode IN ('manual', 'auto_safe', 'auto')),\n        process_isolation TEXT NOT NULL CHECK (\n            process_isolation IN ('host', 'native_sandbox')\n        ),\n        workspace_root_digest TEXT NOT NULL CHECK (length(workspace_root_digest) = 64),\n        workspace_read_only INTEGER NOT NULL CHECK (workspace_read_only IN (0, 1)),\n        tool_schema_digest TEXT NOT NULL CHECK (length(tool_schema_digest) = 64),\n        run_policy_digest TEXT NOT NULL CHECK (length(run_policy_digest) = 64),\n        permission_profile_digest TEXT NOT NULL CHECK (length(permission_profile_digest) = 64),\n        policy_version TEXT NOT NULL,\n        schema_version INTEGER NOT NULL CHECK (schema_version = 9),\n        source_revisions_json TEXT NOT NULL,\n        grant_id TEXT REFERENCES capability_grants(grant_id),\n        grant_digest TEXT CHECK (grant_digest IS NULL OR length(grant_digest) = 64),\n        granted_capabilities_json TEXT NOT NULL,\n        capability_isolations_json TEXT NOT NULL,\n        created_at_unix INTEGER NOT NULL\n    , mcp_review_evidence_json TEXT NOT NULL DEFAULT '[]')",
    "CREATE TABLE preference_evidence (\n        evidence_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        job_id TEXT NOT NULL UNIQUE REFERENCES preference_review_jobs(job_id),\n        turn_id TEXT NOT NULL REFERENCES turns(turn_id),\n        source_kind TEXT NOT NULL CHECK (source_kind = 'user_turn'),\n        actor TEXT NOT NULL CHECK (actor = 'user'),\n        excerpt_redacted TEXT,\n        excerpt_bytes INTEGER NOT NULL CHECK (excerpt_bytes BETWEEN 0 AND 2048),\n        content_digest TEXT NOT NULL CHECK (length(content_digest) = 64),\n        safety_rejection_code TEXT CHECK (\n            safety_rejection_code IS NULL OR safety_rejection_code IN (\n                'secret_material', 'prohibited_personal_data',\n                'hidden_unicode_control', 'capability_authorization',\n                'prompt_injection'\n            )\n        ),\n        observed_at_unix INTEGER NOT NULL,\n        created_at_unix INTEGER NOT NULL,\n        CHECK (excerpt_redacted IS NULL OR length(excerpt_redacted) BETWEEN 1 AND 512),\n        CHECK ((excerpt_redacted IS NULL AND excerpt_bytes = 0)\n            OR (excerpt_redacted IS NOT NULL AND excerpt_bytes > 0)),\n        CHECK (safety_rejection_code IS NULL OR excerpt_redacted IS NULL)\n    )",
    'CREATE TABLE preference_proposal_evidence (\n        workspace_id TEXT NOT NULL,\n        proposal_id TEXT NOT NULL REFERENCES preference_proposals(proposal_id),\n        evidence_id TEXT NOT NULL REFERENCES preference_evidence(evidence_id),\n        PRIMARY KEY (proposal_id, evidence_id)\n    )',
    "CREATE TABLE preference_proposals (\n        proposal_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        job_id TEXT NOT NULL REFERENCES preference_review_jobs(job_id),\n        evidence_id TEXT NOT NULL REFERENCES preference_evidence(evidence_id),\n        operation TEXT NOT NULL CHECK (operation IN ('add', 'replace', 'remove')),\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace')),\n        preference_id TEXT,\n        operation_json TEXT NOT NULL CHECK (length(operation_json) BETWEEN 2 AND 8192),\n        operation_bytes INTEGER NOT NULL CHECK (operation_bytes BETWEEN 2 AND 8192),\n        operation_digest TEXT NOT NULL CHECK (length(operation_digest) = 64),\n        expected_target_revision INTEGER CHECK (\n            expected_target_revision IS NULL OR expected_target_revision >= 1\n        ),\n        expected_document_revision INTEGER NOT NULL CHECK (expected_document_revision >= 0),\n        status TEXT NOT NULL CHECK (\n            status IN ('proposed', 'accepted', 'edited_and_accepted', 'rejected',\n                       'suppressed', 'stale', 'conflict', 'expired')\n        ),\n        final_operation_json TEXT,\n        final_operation_bytes INTEGER CHECK (\n            final_operation_bytes IS NULL OR final_operation_bytes BETWEEN 2 AND 8192\n        ),\n        decision_command_id TEXT,\n        decision_reason TEXT,\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        resolved_at_unix INTEGER,\n        UNIQUE (workspace_id, job_id, operation_digest),\n        CHECK ((final_operation_json IS NULL) = (final_operation_bytes IS NULL)),\n        CHECK (resolved_at_unix IS NULL OR resolved_at_unix >= created_at_unix)\n    )",
    "CREATE TABLE preference_review_jobs (\n        job_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT REFERENCES sessions(session_id),\n        turn_id TEXT NOT NULL REFERENCES turns(turn_id),\n        review_version INTEGER NOT NULL CHECK (review_version >= 1),\n        status TEXT NOT NULL CHECK (\n            status IN ('pending', 'running', 'completed', 'failed', 'exhausted',\n                       'cancelled', 'superseded')\n        ),\n        source_global_revision INTEGER NOT NULL CHECK (source_global_revision >= 0),\n        source_workspace_revision INTEGER NOT NULL CHECK (source_workspace_revision >= 0),\n        active_snapshot_json TEXT NOT NULL CHECK (length(active_snapshot_json) >= 2),\n        active_snapshot_count INTEGER NOT NULL CHECK (\n            active_snapshot_count BETWEEN 0 AND 256\n        ),\n        active_snapshot_bytes INTEGER NOT NULL CHECK (\n            active_snapshot_bytes BETWEEN 2 AND 196608\n        ),\n        active_snapshot_digest TEXT NOT NULL CHECK (length(active_snapshot_digest) = 64),\n        reviewer_provider_id TEXT,\n        reviewer_model_id TEXT,\n        reviewer_prompt_version TEXT NOT NULL CHECK (\n            length(reviewer_prompt_version) BETWEEN 1 AND 64\n        ),\n        reviewer_schema_version TEXT NOT NULL CHECK (\n            length(reviewer_schema_version) BETWEEN 1 AND 64\n        ),\n        lease_id TEXT UNIQUE,\n        lease_expires_at_unix INTEGER,\n        attempt_count INTEGER NOT NULL CHECK (attempt_count BETWEEN 0 AND 3),\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        started_at_unix INTEGER,\n        completed_at_unix INTEGER,\n        failure_code TEXT CHECK (\n            failure_code IS NULL OR failure_code IN (\n                'context_budget', 'request_budget', 'safety_rejected',\n                'snapshot_invalid', 'provider_unavailable', 'timeout',\n                'malformed_output', 'lease_lost', 'cancelled', 'persistence'\n            )\n        ),\n        UNIQUE (workspace_id, turn_id, review_version),\n        CHECK (status != 'running' OR (\n            lease_id IS NOT NULL AND lease_expires_at_unix IS NOT NULL\n        )),\n        CHECK (status IN ('failed', 'exhausted') OR failure_code IS NULL),\n        CHECK (status IN ('pending', 'running') OR completed_at_unix IS NOT NULL),\n        CHECK (status NOT IN ('pending', 'running') OR completed_at_unix IS NULL),\n        CHECK (completed_at_unix IS NULL OR completed_at_unix >= created_at_unix)\n    )",
    'CREATE TABLE preference_write_batch_proposals (\n        workspace_id TEXT NOT NULL,\n        batch_id TEXT NOT NULL REFERENCES preference_write_batches(batch_id),\n        proposal_id TEXT NOT NULL REFERENCES preference_proposals(proposal_id),\n        PRIMARY KEY (batch_id, proposal_id)\n    )',
    "CREATE TABLE preference_write_batches (\n        batch_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace')),\n        command_id TEXT NOT NULL,\n        operations_json TEXT NOT NULL CHECK (length(operations_json) BETWEEN 2 AND 196608),\n        operations_bytes INTEGER NOT NULL CHECK (\n            operations_bytes BETWEEN 2 AND 196608\n        ),\n        allocated_add_ids_json TEXT NOT NULL CHECK (length(allocated_add_ids_json) BETWEEN 2 AND 4096),\n        proposal_ids_json TEXT NOT NULL CHECK (length(proposal_ids_json) BETWEEN 2 AND 8192),\n        expected_document_revision INTEGER NOT NULL CHECK (expected_document_revision >= 0),\n        before_document_revision INTEGER NOT NULL CHECK (before_document_revision >= 0),\n        before_document_digest TEXT NOT NULL CHECK (length(before_document_digest) = 64),\n        after_document_revision INTEGER NOT NULL CHECK (after_document_revision >= 0),\n        after_document_digest TEXT NOT NULL CHECK (length(after_document_digest) = 64),\n        before_document_json TEXT,\n        after_document_json TEXT,\n        status TEXT NOT NULL CHECK (\n            status IN ('prepared', 'yaml_applied', 'finalized', 'needs_resolution', 'failed')\n        ),\n        recovery_code TEXT,\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        prepared_at_unix INTEGER,\n        applied_at_unix INTEGER,\n        finalized_at_unix INTEGER,\n        UNIQUE (workspace_id, command_id),\n        CHECK (before_document_json IS NULL OR length(before_document_json) BETWEEN 2 AND 196608),\n        CHECK (after_document_json IS NULL OR length(after_document_json) BETWEEN 2 AND 196608),\n        CHECK (finalized_at_unix IS NULL OR finalized_at_unix >= created_at_unix)\n    )",
    'CREATE TABLE project_knowledge_evidence (\n        workspace_id TEXT NOT NULL,\n        knowledge_revision_id TEXT NOT NULL\n            REFERENCES project_knowledge_revisions(knowledge_revision_id),\n        evidence_id TEXT NOT NULL REFERENCES learning_evidence(evidence_id),\n        PRIMARY KEY (knowledge_revision_id, evidence_id)\n    )',
    "CREATE TABLE project_knowledge_heads (\n        knowledge_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        semantic_key TEXT NOT NULL CHECK (length(semantic_key) BETWEEN 1 AND 128),\n        category TEXT NOT NULL CHECK (category IN (\n            'architecture', 'convention', 'decision', 'environment', 'domain', 'other'\n        )),\n        status TEXT NOT NULL CHECK (\n            status IN ('active', 'disabled', 'disputed', 'deleted')\n        ),\n        current_revision_id TEXT REFERENCES project_knowledge_revisions(knowledge_revision_id),\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        UNIQUE (workspace_id, semantic_key),\n        CHECK (updated_at_unix >= created_at_unix)\n    )",
    "CREATE TABLE project_knowledge_revisions (\n        knowledge_revision_id TEXT PRIMARY KEY,\n        knowledge_id TEXT NOT NULL REFERENCES project_knowledge_heads(knowledge_id),\n        workspace_id TEXT NOT NULL,\n        revision INTEGER NOT NULL CHECK (revision >= 1),\n        statement TEXT NOT NULL CHECK (length(statement) BETWEEN 1 AND 4096),\n        statement_digest TEXT NOT NULL CHECK (length(statement_digest) = 64),\n        source_candidate_id TEXT REFERENCES learning_candidates(candidate_id),\n        source_decision_id TEXT REFERENCES learning_candidate_decisions(decision_id),\n        supersedes_revision_id TEXT REFERENCES project_knowledge_revisions(knowledge_revision_id),\n        sensitivity TEXT NOT NULL CHECK (\n            sensitivity IN ('normal', 'personal', 'sensitive', 'prohibited')\n        ),\n        valid_from_unix INTEGER,\n        valid_until_unix INTEGER,\n        created_at_unix INTEGER NOT NULL,\n        last_confirmed_at_unix INTEGER NOT NULL,\n        UNIQUE (knowledge_id, revision),\n        CHECK (source_candidate_id IS NOT NULL OR source_decision_id IS NOT NULL),\n        CHECK (\n            valid_until_unix IS NULL OR valid_from_unix IS NULL\n            OR valid_until_unix > valid_from_unix\n        ),\n        CHECK (last_confirmed_at_unix >= created_at_unix)\n    )",
    "CREATE TABLE promotion_operations (\n        operation_id TEXT PRIMARY KEY,\n        command_id TEXT NOT NULL,\n        request_digest TEXT NOT NULL CHECK (length(request_digest) = 64),\n        workspace_id TEXT NOT NULL,\n        candidate_id TEXT NOT NULL REFERENCES learning_candidates(candidate_id),\n        candidate_row_version INTEGER NOT NULL CHECK (candidate_row_version >= 1),\n        target TEXT NOT NULL CHECK (length(target) BETWEEN 1 AND 64),\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace', 'session', 'task')),\n        path TEXT NOT NULL CHECK (length(path) BETWEEN 1 AND 256),\n        prepared_change_json TEXT NOT NULL CHECK (length(prepared_change_json) BETWEEN 2 AND 8192),\n        prepared_change_digest TEXT NOT NULL CHECK (length(prepared_change_digest) = 64),\n        state TEXT NOT NULL CHECK (\n            state IN ('prepared', 'finalized', 'aborted', 'needs_resolution')\n        ),\n        before_revision INTEGER CHECK (before_revision IS NULL OR before_revision >= 0),\n        before_digest TEXT CHECK (before_digest IS NULL OR length(before_digest) = 64),\n        after_digest TEXT CHECK (after_digest IS NULL OR length(after_digest) = 64),\n        applied_revision INTEGER CHECK (applied_revision IS NULL OR applied_revision >= 1),\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        failure_code TEXT CHECK (\n            failure_code IS NULL OR failure_code IN (\n                'stale', 'conflict', 'validation', 'filesystem', 'yaml', 'needs_recovery',\n                'internal'\n            )\n        ),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        prepared_at_unix INTEGER,\n        finalized_at_unix INTEGER,\n        UNIQUE (workspace_id, command_id),\n        CHECK (updated_at_unix >= created_at_unix),\n        CHECK (state != 'finalized' OR applied_revision IS NOT NULL),\n        CHECK (state = 'finalized' OR finalized_at_unix IS NULL)\n    )",
    'CREATE TABLE recovery_receipts (\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        command_id TEXT NOT NULL,\n        request_digest TEXT NOT NULL,\n        report_id TEXT NOT NULL REFERENCES recovery_reports(report_id),\n        item_id TEXT,\n        resolution TEXT NOT NULL,\n        PRIMARY KEY (session_id, command_id)\n    )',
    "CREATE TABLE recovery_reports (\n        report_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        turn_id TEXT,\n        agent_run_id TEXT,\n        status TEXT NOT NULL\n            CHECK (status IN ('open', 'resolved', 'quarantined')),\n        payload_json TEXT NOT NULL,\n        payload_bytes INTEGER NOT NULL CHECK (payload_bytes >= 0),\n        created_at_unix INTEGER NOT NULL,\n        resolved_at_unix INTEGER\n    )",
    "CREATE TABLE runtime_control_queue (\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        position INTEGER NOT NULL CHECK (position >= 1),\n        kind TEXT NOT NULL CHECK (kind IN ('steer', 'follow_up')),\n        client_message_id TEXT NOT NULL,\n        text TEXT NOT NULL CHECK (length(text) BETWEEN 1 AND 4096),\n        status TEXT NOT NULL CHECK (status IN ('pending', 'consumed', 'superseded')),\n        created_at_unix INTEGER NOT NULL,\n        consumed_at_unix INTEGER,\n        PRIMARY KEY (session_id, position),\n        UNIQUE (session_id, client_message_id),\n        CHECK (\n            (status = 'consumed' AND consumed_at_unix IS NOT NULL)\n            OR (status != 'consumed' AND consumed_at_unix IS NULL)\n        )\n    )",
    'CREATE TABLE session_metadata (session_id TEXT PRIMARY KEY REFERENCES sessions(session_id), title TEXT CHECK(title IS NULL OR length(title)<=120), pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN (0,1)), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>=1))',
    'CREATE TABLE session_scope_revisions (session_id TEXT NOT NULL REFERENCES sessions(session_id), scope TEXT NOT NULL CHECK(length(scope)<=128), revision INTEGER NOT NULL CHECK(revision>=1), PRIMARY KEY(session_id, scope))',
    "CREATE TABLE sessions (\n        session_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        lifecycle TEXT NOT NULL\n            CHECK (lifecycle IN ('active', 'archived', 'deleted')),\n        health TEXT NOT NULL\n            CHECK (health IN ('ok', 'needs_recovery', 'quarantined', 'read_only')),\n        current_task_run_id TEXT,\n        conversation_position INTEGER NOT NULL CHECK (conversation_position >= 0),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL\n    , parent_session_id TEXT REFERENCES sessions(session_id), parent_cut_record_id TEXT, parent_cut_position INTEGER\n        CHECK (parent_cut_position IS NULL OR parent_cut_position >= 1), parent_checkpoint_id TEXT\n        REFERENCES context_checkpoints(checkpoint_id), fork_reason TEXT)",
    "CREATE TABLE skill_catalog_operations (\n        operation_id TEXT PRIMARY KEY,\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace')),\n        scope_id TEXT NOT NULL CHECK (\n            (scope = 'global' AND scope_id = '') OR\n            (scope = 'workspace' AND substr(scope_id, 1, 3) = 'ws_' AND length(scope_id) > 3)\n        ),\n        skill_id TEXT NOT NULL,\n        version_id TEXT,\n        operation TEXT NOT NULL CHECK (\n            operation IN (\n                'import', 'enable', 'disable', 'pin', 'unpin', 'rollback',\n                'remove', 'draft_create', 'draft_accept', 'usage_record'\n            )\n        ),\n        disposition TEXT NOT NULL CHECK (\n            disposition IN ('applied', 'rejected', 'failed')\n        ),\n        evidence_digest TEXT NOT NULL,\n        reason TEXT,\n        created_at_unix INTEGER NOT NULL\n    )",
    "CREATE TABLE skill_definitions (\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace')),\n        scope_id TEXT NOT NULL CHECK (\n            (scope = 'global' AND scope_id = '') OR\n            (scope = 'workspace' AND substr(scope_id, 1, 3) = 'ws_' AND length(scope_id) > 3)\n        ),\n        skill_id TEXT NOT NULL,\n        name TEXT NOT NULL,\n        source_kind TEXT NOT NULL\n            CHECK (source_kind IN ('builtin', 'user_authored', 'generated', 'imported')),\n        availability TEXT NOT NULL\n            CHECK (availability IN ('available', 'invalid', 'conflicted', 'unavailable')),\n        conflict_status TEXT NOT NULL\n            CHECK (conflict_status IN ('none', 'identity_conflict', 'name_conflict')),\n        effective_trust TEXT NOT NULL\n            CHECK (effective_trust IN ('builtin', 'user', 'generated', 'imported', 'unknown')),\n        updated_at_unix INTEGER NOT NULL,\n        PRIMARY KEY (scope, scope_id, skill_id)\n    )",
    'CREATE TABLE skill_draft_validations (\n        validation_id TEXT PRIMARY KEY,\n        draft_id TEXT NOT NULL REFERENCES skill_drafts(draft_id),\n        revision INTEGER NOT NULL CHECK (revision >= 1),\n        validator_version TEXT NOT NULL CHECK (length(validator_version) BETWEEN 1 AND 64),\n        valid INTEGER NOT NULL CHECK (valid IN (0, 1)),\n        report_json TEXT NOT NULL CHECK (length(report_json) BETWEEN 2 AND 32768),\n        report_bytes INTEGER NOT NULL CHECK (report_bytes BETWEEN 2 AND 32768),\n        report_digest TEXT NOT NULL CHECK (length(report_digest) = 64),\n        created_at_unix INTEGER NOT NULL\n    )',
    "CREATE TABLE skill_drafts (\n        draft_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        candidate_id TEXT NOT NULL REFERENCES learning_candidates(candidate_id),\n        root_draft_id TEXT NOT NULL,\n        parent_draft_id TEXT REFERENCES skill_drafts(draft_id),\n        revision INTEGER NOT NULL CHECK (revision >= 1),\n        status TEXT NOT NULL CHECK (\n            status IN ('draft', 'validated', 'accepted', 'rejected', 'superseded')\n        ),\n        skill_id TEXT NOT NULL,\n        name TEXT NOT NULL,\n        display_version TEXT,\n        scope_id TEXT NOT NULL,\n        candidate_fingerprint TEXT NOT NULL CHECK (length(candidate_fingerprint) = 64),\n        evidence_refs_json TEXT NOT NULL,\n        package_ref TEXT NOT NULL,\n        tree_digest TEXT NOT NULL CHECK (length(tree_digest) = 64),\n        file_count INTEGER NOT NULL CHECK (file_count BETWEEN 0 AND 4096),\n        total_bytes INTEGER NOT NULL CHECK (total_bytes BETWEEN 0 AND 16777216),\n        validation_id TEXT,\n        accepted_version_id TEXT REFERENCES skill_versions(version_id),\n        acceptance_command_id TEXT,\n        rejection_reason TEXT,\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        UNIQUE (root_draft_id, revision),\n        UNIQUE (candidate_id, revision)\n    )",
    "CREATE TABLE skill_usage (\n        usage_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        agent_run_id TEXT NOT NULL REFERENCES agent_runs(agent_run_id),\n        task_run_id TEXT REFERENCES task_runs(task_run_id),\n        selection_id TEXT,\n        skill_id TEXT NOT NULL,\n        version_id TEXT NOT NULL REFERENCES skill_versions(version_id),\n        activation_reason TEXT NOT NULL,\n        status TEXT NOT NULL CHECK (\n            status IN ('succeeded', 'failed', 'cancelled', 'interrupted', 'unknown')\n        ),\n        user_correction INTEGER NOT NULL CHECK (user_correction IN (0, 1)),\n        input_tokens INTEGER NOT NULL CHECK (input_tokens BETWEEN 0 AND 1000000000),\n        output_tokens INTEGER NOT NULL CHECK (output_tokens BETWEEN 0 AND 1000000000),\n        duration_ms INTEGER NOT NULL CHECK (duration_ms BETWEEN 0 AND 1000000000),\n        tool_call_count INTEGER NOT NULL CHECK (tool_call_count BETWEEN 0 AND 1000000000),\n        artifact_refs_json TEXT NOT NULL,\n        facts_digest TEXT NOT NULL CHECK (length(facts_digest) = 64),\n        created_at_unix INTEGER NOT NULL,\n        UNIQUE (agent_run_id, skill_id, version_id, created_at_unix)\n    )",
    "CREATE TABLE skill_versions (\n        version_id TEXT PRIMARY KEY,\n        scope TEXT NOT NULL CHECK (scope IN ('global', 'workspace')),\n        scope_id TEXT NOT NULL CHECK (\n            (scope = 'global' AND scope_id = '') OR\n            (scope = 'workspace' AND substr(scope_id, 1, 3) = 'ws_' AND length(scope_id) > 3)\n        ),\n        skill_id TEXT NOT NULL,\n        display_version TEXT,\n        tree_digest TEXT NOT NULL,\n        file_count INTEGER NOT NULL CHECK (file_count >= 0),\n        total_bytes INTEGER NOT NULL CHECK (total_bytes >= 0),\n        source_kind TEXT NOT NULL\n            CHECK (source_kind IN ('builtin', 'user_authored', 'generated', 'imported')),\n        provenance TEXT NOT NULL,\n        evidence_refs_json TEXT NOT NULL,\n        effective_trust TEXT NOT NULL\n            CHECK (effective_trust IN ('builtin', 'user', 'generated', 'imported', 'unknown')),\n        installed_at_unix INTEGER NOT NULL,\n        FOREIGN KEY (scope, scope_id, skill_id)\n            REFERENCES skill_definitions (scope, scope_id, skill_id)\n    )",
    "CREATE TABLE store_identity (\n        singleton INTEGER PRIMARY KEY CHECK (singleton = 1),\n        application_name TEXT NOT NULL\n            CHECK (application_name = 'morrow-operational-store'),\n        schema_version INTEGER NOT NULL,\n        created_at_unix INTEGER NOT NULL\n    )",
    "CREATE TABLE task_command_receipts (\n        command_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        task_run_id TEXT REFERENCES task_runs(task_run_id),\n        operation TEXT NOT NULL,\n        request_digest TEXT NOT NULL CHECK (length(request_digest) = 64),\n        disposition TEXT NOT NULL CHECK (disposition IN ('accepted', 'replay', 'conflict')),\n        result_task_run_id TEXT REFERENCES task_runs(task_run_id),\n        outcome_id TEXT REFERENCES task_outcomes(outcome_id),\n        task_status TEXT,\n        row_version INTEGER,\n        created_at_unix INTEGER NOT NULL\n    )",
    "CREATE TABLE task_outcomes (\n        outcome_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        version INTEGER NOT NULL CHECK (version >= 1),\n        trigger TEXT NOT NULL CHECK (\n            trigger IN ('acceptance', 'snapshot', 'terminal_close')\n        ),\n        task_status TEXT NOT NULL CHECK (\n            task_status IN (\n                'open', 'ready_for_acceptance', 'accepted', 'cancelled',\n                'failed', 'abandoned'\n            )\n        ),\n        payload_json TEXT NOT NULL,\n        payload_bytes INTEGER NOT NULL CHECK (payload_bytes >= 0),\n        created_at_unix INTEGER NOT NULL, artifact_refs_json TEXT NOT NULL DEFAULT '[]',\n        UNIQUE (task_run_id, version)\n    )",
    "CREATE TABLE task_run_transitions (\n        transition_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        from_status TEXT CHECK (\n            from_status IS NULL OR from_status IN (\n                'open', 'ready_for_acceptance', 'accepted', 'cancelled',\n                'failed', 'abandoned'\n            )\n        ),\n        to_status TEXT NOT NULL CHECK (\n            to_status IN (\n                'open', 'ready_for_acceptance', 'accepted', 'cancelled',\n                'failed', 'abandoned'\n            )\n        ),\n        reason TEXT NOT NULL,\n        turn_id TEXT REFERENCES turns(turn_id),\n        command_id TEXT,\n        attempt INTEGER NOT NULL CHECK (attempt >= 1),\n        created_at_unix INTEGER NOT NULL\n    )",
    "CREATE TABLE task_runs (\n        task_run_id TEXT PRIMARY KEY,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        workspace_id TEXT NOT NULL,\n        status TEXT NOT NULL CHECK (\n            status IN (\n                'open', 'ready_for_acceptance', 'accepted', 'cancelled',\n                'failed', 'abandoned'\n            )\n        ),\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        attempt INTEGER NOT NULL CHECK (attempt >= 1),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        accepted_at_unix INTEGER,\n        closed_at_unix INTEGER\n    , purpose TEXT NOT NULL DEFAULT 'user' CHECK(purpose IN ('user','workflow_node')))",
    "CREATE TABLE tool_executions (\n        tool_execution_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        turn_id TEXT NOT NULL REFERENCES turns(turn_id),\n        agent_run_id TEXT NOT NULL REFERENCES agent_runs(agent_run_id),\n        assistant_record_id TEXT REFERENCES conversation_records(record_id),\n        call_id TEXT NOT NULL,\n        ordinal INTEGER NOT NULL CHECK (ordinal >= 1),\n        tool_name TEXT NOT NULL,\n        state TEXT NOT NULL\n            CHECK (state IN (\n                'prepared', 'awaiting_approval', 'executing',\n                'handler_completed', 'closed'\n            )),\n        disposition TEXT NOT NULL\n            CHECK (disposition IN (\n                'pending', 'denied', 'succeeded', 'failed',\n                'cancelled', 'interrupted', 'unknown'\n            )),\n        row_version INTEGER NOT NULL CHECK (row_version >= 1),\n        retry_of_execution_id TEXT REFERENCES tool_executions(tool_execution_id),\n        approval_id TEXT,\n        intent_json TEXT NOT NULL,\n        intent_hash TEXT NOT NULL CHECK (length(intent_hash) = 64),\n        schema_digest TEXT NOT NULL CHECK (length(schema_digest) = 64),\n        permission_context_digest TEXT NOT NULL\n            CHECK (length(permission_context_digest) = 64),\n        result_envelope_json TEXT,\n        facts_json TEXT,\n        error_code TEXT,\n        error_detail TEXT,\n        created_at_unix INTEGER NOT NULL,\n        executing_at_unix INTEGER,\n        handler_completed_at_unix INTEGER,\n        closed_at_unix INTEGER, artifact_refs_json TEXT NOT NULL DEFAULT '[]', permission_snapshot_id TEXT\n        REFERENCES permission_snapshots(permission_snapshot_id), grant_id TEXT\n        REFERENCES capability_grants(grant_id), isolation TEXT CHECK (\n        isolation IS NULL OR isolation IN ('workspace', 'native_sandbox', 'unconfined_host')\n    ), cancel_requested_at_unix INTEGER, cancel_request_reason TEXT,\n        UNIQUE (assistant_record_id, ordinal),\n        CHECK (\n            state != 'closed'\n            OR disposition IN (\n                'denied', 'succeeded', 'failed', 'cancelled',\n                'interrupted', 'unknown'\n            )\n        ),\n        CHECK (state != 'handler_completed' OR disposition != 'pending')\n    )",
    "CREATE TABLE turn_submit_receipts (\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        client_message_id TEXT NOT NULL,\n        request_digest TEXT NOT NULL,\n        disposition TEXT NOT NULL\n            CHECK (disposition IN (\n                'accepted_open', 'accepted_closed', 'recovery', 'conflict'\n            )),\n        turn_id TEXT REFERENCES turns(turn_id),\n        command_id TEXT,\n        PRIMARY KEY (session_id, client_message_id)\n    )",
    'CREATE TABLE turns (\n        turn_id TEXT PRIMARY KEY,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        client_message_id TEXT NOT NULL,\n        created_at_unix INTEGER NOT NULL,\n        UNIQUE (session_id, client_message_id)\n    )',
    'CREATE TABLE workflow_agent_run_refs (\n        agent_run_id TEXT PRIMARY KEY REFERENCES agent_runs(agent_run_id),\n        node_run_id TEXT NOT NULL UNIQUE REFERENCES workflow_node_runs(node_run_id)\n    )',
    "CREATE TABLE workflow_artifact_bindings (\n        workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        node_run_id TEXT NOT NULL DEFAULT '',\n        direction TEXT NOT NULL CHECK(direction IN ('input','output')),\n        name TEXT NOT NULL,\n        artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=2048),\n        PRIMARY KEY(workflow_run_id, node_run_id, direction, name)\n    )",
    'CREATE TABLE workflow_definition_heads (\n        workspace_id TEXT NOT NULL,\n        workflow_definition_id TEXT NOT NULL,\n        workflow_revision_id TEXT NOT NULL,\n        body_json TEXT NOT NULL CHECK(length(body_json)<=2048),\n        PRIMARY KEY(workspace_id, workflow_definition_id),\n        FOREIGN KEY(workspace_id, workflow_definition_id, workflow_revision_id)\n          REFERENCES workflow_revisions(workspace_id, workflow_definition_id, workflow_revision_id)\n    )',
    'CREATE TABLE workflow_draft_versions (\n        workspace_id TEXT NOT NULL,\n        draft_id TEXT NOT NULL,\n        version INTEGER NOT NULL CHECK(version>=1),\n        command_id TEXT NOT NULL,\n        body_json TEXT NOT NULL CHECK(length(body_json)<=524288),\n        PRIMARY KEY(workspace_id,draft_id,version),\n        FOREIGN KEY(workspace_id,draft_id) REFERENCES workflow_drafts(workspace_id,draft_id)\n    )',
    "CREATE TABLE workflow_drafts (\n        draft_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        workflow_definition_id TEXT NOT NULL,\n        status TEXT NOT NULL CHECK(status IN (\n            'draft','validating','valid','invalid','rejected','frozen'\n        )),\n        row_version INTEGER NOT NULL CHECK(row_version >= 1),\n        body_json TEXT NOT NULL CHECK(length(body_json) <= 524288),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL\n    )",
    'CREATE TABLE workflow_evaluations (\n            record_id TEXT PRIMARY KEY,\n            workspace_id TEXT NOT NULL,\n            body_json TEXT NOT NULL CHECK(length(body_json) <= 32768)\n        )',
    'CREATE TABLE workflow_feedback (\n            record_id TEXT PRIMARY KEY,\n            workspace_id TEXT NOT NULL,\n            body_json TEXT NOT NULL CHECK(length(body_json) <= 32768)\n        )',
    'CREATE TABLE workflow_leaf_ownership (\n        node_run_id TEXT PRIMARY KEY REFERENCES workflow_node_runs(node_run_id),\n        session_id TEXT NOT NULL UNIQUE REFERENCES sessions(session_id),\n        task_run_id TEXT NOT NULL UNIQUE REFERENCES task_runs(task_run_id)\n    )',
    "CREATE TABLE workflow_node_runs (\n        node_run_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        node_id TEXT NOT NULL,\n        attempt INTEGER NOT NULL CHECK(attempt=1),\n        status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled','blocked')),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=16384),\n        UNIQUE(workflow_run_id, node_id, attempt)\n    )",
    "CREATE TABLE workflow_node_segments (\n        segment_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        node_run_id TEXT NOT NULL REFERENCES workflow_node_runs(node_run_id),\n        ordinal INTEGER NOT NULL CHECK(ordinal >= 1),\n        leaf_session_id TEXT REFERENCES sessions(session_id),\n        leaf_task_run_id TEXT REFERENCES task_runs(task_run_id),\n        agent_run_id TEXT,\n        turn_id TEXT,\n        status TEXT NOT NULL CHECK(status IN ('active','interrupted','completed')),\n        pause_reason TEXT CHECK(pause_reason IS NULL OR pause_reason IN ('user_interrupt','node_boundary','provider_failure','process_interrupt')),\n        previous_segment_id TEXT REFERENCES workflow_node_segments(segment_id),\n        accepted_command_id TEXT CHECK(accepted_command_id IS NULL OR length(accepted_command_id) <= 128),\n        row_version INTEGER NOT NULL CHECK(row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        body_json TEXT NOT NULL CHECK(length(body_json)<=4096),\n        UNIQUE(workflow_run_id, node_run_id, ordinal)\n    )",
    "CREATE TABLE workflow_node_steers (\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        workflow_run_id TEXT NOT NULL,\n        node_run_id TEXT NOT NULL,\n        node_id TEXT,\n        graph_revision_id TEXT NOT NULL,\n        client_message_id TEXT NOT NULL,\n        text TEXT NOT NULL CHECK (length(text) BETWEEN 1 AND 4096),\n        status TEXT NOT NULL CHECK (status IN ('pending', 'consumed', 'expired')),\n        created_at_unix INTEGER NOT NULL,\n        consumed_at_unix INTEGER,\n        PRIMARY KEY (session_id, client_message_id),\n        CHECK (\n            (status = 'consumed' AND consumed_at_unix IS NOT NULL)\n            OR (status != 'consumed' AND consumed_at_unix IS NULL)\n        )\n    )",
    "CREATE TABLE workflow_pause_points (\n        pause_point_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        owner TEXT NOT NULL CHECK(owner IN ('workflow_run','planning_operation','chat_turn')),\n        owner_id TEXT NOT NULL,\n        control_generation INTEGER NOT NULL CHECK(control_generation >= 1),\n        command_id TEXT NOT NULL CHECK(length(command_id) BETWEEN 1 AND 128),\n        reason TEXT NOT NULL CHECK(reason IN ('user_interrupt','node_boundary','provider_failure','process_interrupt')),\n        lifecycle TEXT NOT NULL CHECK(lifecycle IN ('requested','quiescing','suspended','resumed')),\n        node_run_id TEXT,\n        segment_id TEXT REFERENCES workflow_node_segments(segment_id),\n        requested_at_unix INTEGER NOT NULL,\n        suspended_at_unix INTEGER,\n        resumed_at_unix INTEGER,\n        continuation_segment_id TEXT,\n        continuation_command_id TEXT,\n        continuation_input TEXT CHECK(continuation_input IS NULL OR length(continuation_input) BETWEEN 1 AND 4096),\n        cancel_command_id TEXT CHECK(cancel_command_id IS NULL OR length(cancel_command_id) <= 128),\n        cancel_reason TEXT CHECK(cancel_reason IS NULL OR length(cancel_reason) <= 256),\n        cancelled_at_unix INTEGER,\n        row_version INTEGER NOT NULL CHECK(row_version >= 1),\n        created_at_unix INTEGER NOT NULL,\n        updated_at_unix INTEGER NOT NULL,\n        body_json TEXT NOT NULL CHECK(length(body_json)<=16384),\n        UNIQUE(workspace_id, owner, owner_id, control_generation),\n        UNIQUE(workspace_id, owner, owner_id, command_id)\n    )",
    "CREATE TABLE workflow_plan_decisions (\n        plan_decision_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        command_id TEXT NOT NULL,\n        decision TEXT NOT NULL CHECK(decision IN (\n            'start','accept_change','save_candidate','reject_change',\n            'resume','discard','cancel_generation'\n        )),\n        result_id TEXT,\n        body_json TEXT NOT NULL CHECK(length(body_json)<=524288),\n        UNIQUE(workspace_id, command_id)\n    )",
    'CREATE TABLE workflow_planning_artifacts (\n        workspace_id TEXT NOT NULL,\n        planning_binding_id TEXT NOT NULL REFERENCES workflow_planning_bindings(planning_binding_id),\n        artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),\n        PRIMARY KEY(planning_binding_id,artifact_id)\n    )',
    "CREATE TABLE workflow_planning_bindings (\n        planning_binding_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL REFERENCES sessions(session_id),\n        current_draft_id TEXT,\n        status TEXT NOT NULL CHECK(status IN ('active','closed','superseded')),\n        row_version INTEGER NOT NULL CHECK(row_version>=1),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=524288),\n        UNIQUE(workspace_id,session_id,planning_binding_id),\n        FOREIGN KEY(workspace_id,current_draft_id)\n          REFERENCES workflow_drafts(workspace_id,draft_id)\n    )",
    'CREATE TABLE workflow_planning_events (\n        sequence INTEGER PRIMARY KEY AUTOINCREMENT,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL,\n        body_json TEXT NOT NULL CHECK(length(body_json)<=2048)\n    )',
    "CREATE TABLE workflow_planning_operations (\n        planning_operation_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        session_id TEXT NOT NULL,\n        planning_binding_id TEXT NOT NULL,\n        command_id TEXT NOT NULL,\n        status TEXT NOT NULL CHECK(status IN ('queued','running','succeeded','failed','cancelled','expired')),\n        row_version INTEGER NOT NULL CHECK(row_version>=1),\n        result_draft_id TEXT,\n        result_draft_version INTEGER,\n        body_json TEXT NOT NULL CHECK(length(body_json)<=524288),\n        UNIQUE(workspace_id,command_id),\n        FOREIGN KEY(workspace_id,session_id,planning_binding_id)\n          REFERENCES workflow_planning_bindings(workspace_id,session_id,planning_binding_id),\n        FOREIGN KEY(workspace_id,result_draft_id,result_draft_version)\n          REFERENCES workflow_draft_versions(workspace_id,draft_id,version),\n        CHECK((status='succeeded')=(result_draft_id IS NOT NULL AND result_draft_version IS NOT NULL))\n    )",
    "CREATE TABLE workflow_planning_pause_facts (\n        sequence INTEGER PRIMARY KEY AUTOINCREMENT,\n        workspace_id TEXT NOT NULL,\n        planning_operation_id TEXT NOT NULL REFERENCES workflow_planning_operations(planning_operation_id),\n        command_id TEXT NOT NULL,\n        fact_kind TEXT NOT NULL CHECK(fact_kind IN ('pause','resume','shutdown')),\n        lifecycle TEXT NOT NULL CHECK(lifecycle IN ('requested','quiescing','suspended','resumed')),\n        reason TEXT NOT NULL CHECK(reason IN ('user_interrupt','shutdown')),\n        control_generation INTEGER NOT NULL CHECK(control_generation>=1),\n        rebuild_json TEXT CHECK(rebuild_json IS NULL OR length(rebuild_json)<=524288),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=4096),\n        created_at TEXT NOT NULL,\n        UNIQUE(workspace_id,planning_operation_id,command_id,fact_kind,lifecycle)\n    )",
    "CREATE TABLE workflow_planning_request_outcomes (\n        workspace_id TEXT NOT NULL,\n        planning_operation_id TEXT NOT NULL REFERENCES workflow_planning_operations(planning_operation_id),\n        layer TEXT NOT NULL CHECK(layer IN ('model_request','candidate_validation','planning_operation')),\n        attempt INTEGER NOT NULL CHECK(attempt>=1),\n        request_sequence INTEGER NOT NULL CHECK(request_sequence>=1),\n        outcome TEXT NOT NULL,\n        started_at TEXT NOT NULL,\n        ended_at TEXT,\n        reason TEXT CHECK(reason IS NULL OR length(reason)<=256),\n        revision INTEGER NOT NULL CHECK(revision>=1),\n        body_json TEXT CHECK(body_json IS NULL OR length(body_json)<=8192),\n        PRIMARY KEY(workspace_id,planning_operation_id,layer,attempt,request_sequence,revision)\n    )",
    'CREATE TABLE workflow_planning_requests (\n        planning_operation_id TEXT NOT NULL REFERENCES workflow_planning_operations(planning_operation_id),\n        attempt INTEGER NOT NULL CHECK(attempt BETWEEN 0 AND 2),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=8192),\n        PRIMARY KEY(planning_operation_id,attempt)\n    )',
    'CREATE TABLE workflow_policy_candidates (\n            record_id TEXT PRIMARY KEY,\n            workspace_id TEXT NOT NULL,\n            body_json TEXT NOT NULL CHECK(length(body_json) <= 32768)\n        )',
    'CREATE TABLE workflow_publications (\n        workspace_id TEXT NOT NULL, command_id TEXT NOT NULL, request_hash TEXT NOT NULL,\n        workflow_revision_id TEXT NOT NULL REFERENCES workflow_revisions(workflow_revision_id),\n        PRIMARY KEY(workspace_id, command_id)\n    )',
    'CREATE TABLE workflow_replan_proposals (\n        proposal_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        row_version INTEGER NOT NULL,\n        body_json TEXT NOT NULL CHECK(length(body_json) <= 524288)\n    )',
    'CREATE TABLE workflow_replan_signals (\n        signal_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        node_run_id TEXT NOT NULL UNIQUE REFERENCES workflow_node_runs(node_run_id),\n        consumed_by TEXT,\n        body_json TEXT NOT NULL CHECK(length(body_json) <= 32768)\n    )',
    'CREATE TABLE workflow_revision_nodes (\n        workflow_revision_id TEXT NOT NULL REFERENCES workflow_revisions(workflow_revision_id),\n        node_id TEXT NOT NULL,\n        agent_definition_version_id TEXT NOT NULL REFERENCES agent_definition_versions(version_id),\n        PRIMARY KEY(workflow_revision_id, node_id)\n    )',
    'CREATE TABLE workflow_revision_revocations (\n        workflow_revision_id TEXT PRIMARY KEY REFERENCES workflow_revisions(workflow_revision_id),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=2048)\n    )',
    'CREATE TABLE workflow_revisions (\n        workflow_revision_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        workflow_definition_id TEXT NOT NULL,\n        revision INTEGER NOT NULL CHECK(revision != 0),\n        content_hash TEXT NOT NULL CHECK(length(content_hash)=64),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=262144),\n        UNIQUE(workspace_id, workflow_definition_id, revision),\n        UNIQUE(workspace_id, workflow_definition_id, workflow_revision_id)\n    )',
    'CREATE TABLE workflow_run_artifact_imports (\n        workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        source_workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        source_node_run_id TEXT NOT NULL REFERENCES workflow_node_runs(node_run_id),\n        source_node_id TEXT NOT NULL,\n        output_slot TEXT NOT NULL,\n        artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),\n        contract_json TEXT NOT NULL CHECK(length(contract_json)<=2048),\n        inherited_at_unix INTEGER NOT NULL,\n        PRIMARY KEY(workflow_run_id, source_node_id, output_slot)\n    )',
    "CREATE TABLE workflow_run_execution_nodes (\n        workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        node_id TEXT NOT NULL,\n        topology_ordinal INTEGER NOT NULL CHECK(topology_ordinal >= 0),\n        inclusion_reason TEXT NOT NULL\n            CHECK(inclusion_reason IN ('initial','retained_future','failed_retry')),\n        PRIMARY KEY(workflow_run_id, node_id)\n    )",
    "CREATE TABLE workflow_runs (\n        workflow_run_id TEXT PRIMARY KEY,\n        workspace_id TEXT NOT NULL,\n        workflow_revision_id TEXT NOT NULL REFERENCES workflow_revisions(workflow_revision_id),\n        root_task_run_id TEXT NOT NULL REFERENCES task_runs(task_run_id),\n        status TEXT NOT NULL CHECK(status IN (\n            'queued','running','completed','failed','cancelled','blocked',\n            'draining','paused','superseded'\n        )),\n        pause_requested INTEGER NOT NULL DEFAULT 0 CHECK(pause_requested IN (0,1)),\n        run_relation TEXT NOT NULL DEFAULT 'initial'\n            CHECK(run_relation IN ('initial','continuation','rerun')),\n        lineage_budget_root_run_id TEXT NOT NULL REFERENCES workflow_runs(workflow_run_id),\n        parent_run_id TEXT REFERENCES workflow_runs(workflow_run_id),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=16384)\n    )",
    "CREATE TABLE workflow_task_plan_provenance (\n        workspace_id TEXT NOT NULL,\n        workflow_revision_id TEXT NOT NULL REFERENCES workflow_revisions(workflow_revision_id),\n        planning_binding_id TEXT NOT NULL REFERENCES workflow_planning_bindings(planning_binding_id),\n        plan_decision_id TEXT NOT NULL REFERENCES workflow_plan_decisions(plan_decision_id),\n        origin TEXT NOT NULL CHECK(origin IN ('initial','repair')),\n        body_json TEXT NOT NULL CHECK(length(body_json)<=524288),\n        PRIMARY KEY(workspace_id, workflow_revision_id)\n    )",
