    "CREATE TRIGGER agent_definition_publications_delete_immutable BEFORE DELETE ON agent_definition_publications\n        BEGIN SELECT RAISE(ABORT, 'Agent definition evidence is immutable'); END",
    "CREATE TRIGGER agent_definition_publications_update_immutable BEFORE UPDATE ON agent_definition_publications\n        BEGIN SELECT RAISE(ABORT, 'Agent definition evidence is immutable'); END",
