    "CREATE TRIGGER agent_definition_versions_update_immutable BEFORE UPDATE ON agent_definition_versions\n        BEGIN SELECT RAISE(ABORT, 'Agent definition evidence is immutable'); END",
    "CREATE TRIGGER agent_run_model_requests_workspace_guard_insert\n    BEFORE INSERT ON agent_run_model_requests\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM agent_runs r\n            JOIN turns t ON t.turn_id = r.turn_id\n            JOIN sessions s ON s.session_id = t.session_id\n            WHERE r.agent_run_id = NEW.agent_run_id\n              AND r.session_id = s.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'AgentRun observation workspace mismatch') END;\n    END",
    "CREATE TRIGGER agent_run_model_requests_workspace_guard_update\n    BEFORE UPDATE OF workspace_id, agent_run_id ON agent_run_model_requests\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM agent_runs r\n            JOIN turns t ON t.turn_id = r.turn_id\n            JOIN sessions s ON s.session_id = t.session_id\n            WHERE r.agent_run_id = NEW.agent_run_id\n              AND r.session_id = s.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'AgentRun observation workspace mismatch') END;\n    END",
    "CREATE TRIGGER agent_run_retry_progress_workspace_guard_insert\n    BEFORE INSERT ON agent_run_retry_progress\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM agent_runs r\n            JOIN turns t ON t.turn_id = r.turn_id\n            JOIN sessions s ON s.session_id = t.session_id\n            WHERE r.agent_run_id = NEW.agent_run_id\n              AND r.session_id = s.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'AgentRun retry progress workspace mismatch') END;\n    END",
    "CREATE TRIGGER agent_run_retry_progress_workspace_guard_update\n    BEFORE UPDATE OF workspace_id, agent_run_id ON agent_run_retry_progress\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM agent_runs r\n            JOIN turns t ON t.turn_id = r.turn_id\n            JOIN sessions s ON s.session_id = t.session_id\n            WHERE r.agent_run_id = NEW.agent_run_id\n              AND r.session_id = s.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'AgentRun retry progress workspace mismatch') END;\n    END",
    "CREATE TRIGGER agent_run_terminal_metrics_workspace_guard_insert\n    BEFORE INSERT ON agent_run_terminal_metrics\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM agent_runs r\n            JOIN turns t ON t.turn_id = r.turn_id\n            JOIN sessions s ON s.session_id = t.session_id\n            WHERE r.agent_run_id = NEW.agent_run_id\n              AND r.session_id = s.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'AgentRun metrics workspace mismatch') END;\n    END",
    "CREATE TRIGGER agent_run_terminal_metrics_workspace_guard_update\n    BEFORE UPDATE OF workspace_id, agent_run_id ON agent_run_terminal_metrics\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM agent_runs r\n            JOIN turns t ON t.turn_id = r.turn_id\n            JOIN sessions s ON s.session_id = t.session_id\n            WHERE r.agent_run_id = NEW.agent_run_id\n              AND r.session_id = s.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'AgentRun metrics workspace mismatch') END;\n    END",
    "CREATE TRIGGER agent_runs_definition_identity_insert\n    BEFORE INSERT ON agent_runs\n    WHEN json_extract(NEW.snapshot_json, '$.definition_ref') IS NOT NULL\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM agent_definition_versions v JOIN sessions s ON s.session_id=NEW.session_id\n            WHERE v.workspace_id=s.workspace_id\n              AND v.version_id=json_extract(NEW.snapshot_json, '$.definition_ref.version_id')\n              AND v.definition_id=json_extract(NEW.snapshot_json, '$.definition_ref.definition_id')\n              AND v.content_hash=json_extract(NEW.snapshot_json, '$.definition_ref.content_hash')\n              AND NEW.session_id=json_extract(NEW.snapshot_json, '$.conversation_session_id')\n              AND (\n                  json_extract(NEW.snapshot_json, '$.max_agent_generation_requests')\n                      IS json_extract(v.body_json, '$.source.max_agent_generation_requests')\n                  OR (\n                      json_type(NEW.snapshot_json, '$.max_agent_generation_requests') = 'integer'\n                      AND json_extract(NEW.snapshot_json, '$.max_agent_generation_requests') > 0\n                      AND (\n                          json_type(v.body_json, '$.source.max_agent_generation_requests') = 'null'\n                          OR json_extract(NEW.snapshot_json, '$.max_agent_generation_requests')\n                              <= json_extract(v.body_json, '$.source.max_agent_generation_requests')\n                      )\n                  )\n              )\n        ) THEN RAISE(ABORT, 'Agent definition run evidence mismatch') END;\n    END",
    "CREATE TRIGGER agent_runs_definition_snapshot_immutable\n    BEFORE UPDATE OF snapshot_json, session_id ON agent_runs\n    WHEN json_extract(OLD.snapshot_json, '$.definition_ref') IS NOT NULL\n      OR json_extract(NEW.snapshot_json, '$.definition_ref') IS NOT NULL\n    BEGIN SELECT RAISE(ABORT, 'Agent definition run evidence is immutable'); END",
    "CREATE TRIGGER attachment_identity BEFORE UPDATE OF attachment_id,workspace_id,\n        session_id,command_id,request_json,byte_size ON chat_attachments BEGIN\n        SELECT RAISE(ABORT,'attachment identity is immutable');\n    END",
    "CREATE TRIGGER attachment_scope BEFORE INSERT ON chat_attachments BEGIN\n        SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM sessions\n            WHERE session_id=NEW.session_id AND workspace_id=NEW.workspace_id)\n        THEN RAISE(ABORT,'attachment scope mismatch') END;\n    END",
    "CREATE TRIGGER attachment_submitted BEFORE UPDATE ON chat_attachments\n        WHEN OLD.state='submitted' AND (NEW.state!='submitted'\n        OR NEW.reference_json IS NOT OLD.reference_json) BEGIN\n        SELECT RAISE(ABORT,'submitted attachment is immutable');\n    END",
    "CREATE TRIGGER chat_control_receipts_workspace_guard_insert\n    BEFORE INSERT ON chat_control_receipts\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM sessions s\n            WHERE s.session_id = NEW.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'control receipt Session workspace mismatch') END;\n    END",
    "CREATE TRIGGER chat_interaction_identity BEFORE UPDATE OF\n        interaction_id,workspace_id,session_id,client_message_id,position,\n        request_digest,binding_digest,request_json,binding_json ON chat_interactions BEGIN\n        SELECT RAISE(ABORT, 'interaction binding is immutable');\n    END",
    "CREATE TRIGGER chat_interaction_scope BEFORE INSERT ON chat_interactions BEGIN\n        SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM sessions\n            WHERE session_id=NEW.session_id AND workspace_id=NEW.workspace_id)\n        THEN RAISE(ABORT, 'interaction scope mismatch') END;\n    END",
    "CREATE TRIGGER learning_candidate_decisions_workspace_guard_insert\n    BEFORE INSERT ON learning_candidate_decisions\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_candidates c\n            WHERE c.candidate_id = NEW.candidate_id AND c.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n    END",
    "CREATE TRIGGER learning_candidate_evidence_workspace_guard_insert\n    BEFORE INSERT ON learning_candidate_evidence\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_candidates c\n            JOIN learning_evidence e ON e.evidence_id = NEW.evidence_id\n            WHERE c.candidate_id = NEW.candidate_id\n              AND (c.workspace_id != NEW.workspace_id OR e.workspace_id != NEW.workspace_id)\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n    END",
    "CREATE TRIGGER learning_candidate_workspace_guard_insert\n    BEFORE INSERT ON learning_candidates\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_reviews r\n            WHERE r.review_id = NEW.origin_review_id AND r.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n    END",
    "CREATE TRIGGER learning_evidence_workspace_guard_insert\n    BEFORE INSERT ON learning_evidence\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_reviews r\n            WHERE r.review_id = NEW.origin_review_id AND r.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM task_runs t\n            WHERE t.task_run_id = NEW.task_run_id AND t.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n    END",
    "CREATE TRIGGER learning_review_evidence_workspace_guard_insert\n    BEFORE INSERT ON learning_review_evidence\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_reviews r\n            JOIN learning_evidence e ON e.evidence_id = NEW.evidence_id\n            WHERE r.review_id = NEW.review_id\n              AND (r.workspace_id != NEW.workspace_id OR e.workspace_id != NEW.workspace_id)\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n    END",
    "CREATE TRIGGER learning_reviews_workspace_guard_insert\n    BEFORE INSERT ON learning_reviews\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM task_runs t\n            WHERE t.task_run_id = NEW.task_run_id AND t.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM task_outcomes o\n            WHERE o.outcome_id = NEW.task_outcome_id AND o.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n    END",
    "CREATE TRIGGER learning_reviews_workspace_guard_update\n    BEFORE UPDATE OF workspace_id, task_run_id, task_outcome_id ON learning_reviews\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM task_runs t\n            WHERE t.task_run_id = NEW.task_run_id AND t.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM task_outcomes o\n            WHERE o.outcome_id = NEW.task_outcome_id AND o.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'learning workspace mismatch') END;\n    END",
    "CREATE TRIGGER memory_search_terms_workspace_guard_insert\n    BEFORE INSERT ON memory_search_terms\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM project_knowledge_revisions r\n            WHERE r.knowledge_revision_id = NEW.knowledge_revision_id\n              AND r.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'memory search term workspace mismatch') END;\n    END",
    "CREATE TRIGGER memory_selection_items_workspace_guard_insert\n    BEFORE INSERT ON memory_selection_items\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1\n            FROM memory_selections s\n            JOIN project_knowledge_heads h ON h.knowledge_id = NEW.record_id\n            JOIN project_knowledge_revisions r ON r.knowledge_revision_id = NEW.record_revision_id\n            WHERE s.selection_id = NEW.selection_id\n              AND (s.workspace_id != NEW.workspace_id\n                   OR h.workspace_id != NEW.workspace_id\n                   OR r.workspace_id != NEW.workspace_id\n                   OR r.knowledge_id != NEW.record_id)\n        ) THEN RAISE(ABORT, 'memory selection workspace mismatch') END;\n    END",
    "CREATE TRIGGER plan_decision_immutable BEFORE UPDATE ON workflow_plan_decisions\n        BEGIN SELECT RAISE(ABORT,'plan decision is immutable'); END",
    "CREATE TRIGGER plan_decision_scope BEFORE INSERT ON workflow_plan_decisions BEGIN\n        SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM sessions\n            WHERE session_id=NEW.session_id AND workspace_id=NEW.workspace_id)\n        THEN RAISE(ABORT,'plan decision scope mismatch') END;\n    END",
    "CREATE TRIGGER planning_artifact_scope BEFORE INSERT ON workflow_planning_artifacts BEGIN\n        SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM artifacts a JOIN workflow_planning_bindings b\n          ON b.planning_binding_id=NEW.planning_binding_id\n          WHERE a.artifact_id=NEW.artifact_id AND a.workspace_id=NEW.workspace_id\n            AND b.workspace_id=NEW.workspace_id)\n        THEN RAISE(ABORT,'planning artifact scope mismatch') END;\n    END",
    "CREATE TRIGGER planning_binding_identity BEFORE UPDATE OF planning_binding_id,workspace_id,\n        session_id ON workflow_planning_bindings BEGIN\n        SELECT CASE WHEN OLD.planning_binding_id!=NEW.planning_binding_id\n          OR OLD.workspace_id!=NEW.workspace_id OR OLD.session_id!=NEW.session_id\n        THEN RAISE(ABORT,'planning identity is immutable') END;\n    END",
    "CREATE TRIGGER planning_binding_scope BEFORE INSERT ON workflow_planning_bindings BEGIN\n        SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM sessions\n            WHERE session_id=NEW.session_id AND workspace_id=NEW.workspace_id)\n        THEN RAISE(ABORT,'planning scope mismatch') END;\n    END",
    "CREATE TRIGGER preference_evidence_workspace_guard_insert\n    BEFORE INSERT ON preference_evidence\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM preference_review_jobs j\n            WHERE j.job_id = NEW.job_id\n              AND (j.workspace_id != NEW.workspace_id OR j.turn_id != NEW.turn_id)\n        ) THEN RAISE(ABORT, 'preference evidence workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM turns t\n            JOIN sessions s ON s.session_id = t.session_id\n            WHERE t.turn_id = NEW.turn_id AND s.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'preference evidence workspace mismatch') END;\n    END",
    "CREATE TRIGGER preference_proposal_evidence_workspace_guard_insert\n    BEFORE INSERT ON preference_proposal_evidence\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM preference_proposals p\n            JOIN preference_evidence e ON e.evidence_id = NEW.evidence_id\n            WHERE p.proposal_id = NEW.proposal_id\n              AND (p.workspace_id != NEW.workspace_id OR e.workspace_id != NEW.workspace_id)\n        ) THEN RAISE(ABORT, 'preference proposal evidence workspace mismatch') END;\n    END",
    "CREATE TRIGGER preference_proposals_workspace_guard_insert\n    BEFORE INSERT ON preference_proposals\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM preference_review_jobs j\n            WHERE j.job_id = NEW.job_id AND j.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'preference proposal workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM preference_evidence e\n            WHERE e.evidence_id = NEW.evidence_id AND e.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'preference proposal workspace mismatch') END;\n    END",
    "CREATE TRIGGER preference_review_jobs_workspace_guard_insert\n    BEFORE INSERT ON preference_review_jobs\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM turns t\n            WHERE t.turn_id = NEW.turn_id AND t.session_id IS NULL\n        ) THEN RAISE(ABORT, 'preference turn is invalid') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM sessions s\n            WHERE s.session_id = NEW.session_id AND s.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'preference job workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM turns t\n            WHERE t.turn_id = NEW.turn_id\n              AND NEW.session_id IS NOT NULL\n              AND t.session_id != NEW.session_id\n        ) THEN RAISE(ABORT, 'preference job session mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM turns t\n            WHERE t.turn_id = NEW.turn_id AND t.session_id IN (\n                SELECT s.session_id FROM sessions s WHERE s.workspace_id != NEW.workspace_id\n            )\n        ) THEN RAISE(ABORT, 'preference job workspace mismatch') END;\n    END",
    "CREATE TRIGGER preference_write_batch_proposals_workspace_guard_insert\n    BEFORE INSERT ON preference_write_batch_proposals\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM preference_write_batches b\n            JOIN preference_proposals p ON p.proposal_id = NEW.proposal_id\n            WHERE b.batch_id = NEW.batch_id\n              AND (b.workspace_id != NEW.workspace_id OR p.workspace_id != NEW.workspace_id)\n        ) THEN RAISE(ABORT, 'preference write batch workspace mismatch') END;\n    END",
    "CREATE TRIGGER project_knowledge_evidence_workspace_guard_insert\n    BEFORE INSERT ON project_knowledge_evidence\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1\n            FROM project_knowledge_revisions r\n            JOIN learning_evidence e ON e.evidence_id = NEW.evidence_id\n            WHERE r.knowledge_revision_id = NEW.knowledge_revision_id\n              AND (r.workspace_id != NEW.workspace_id OR e.workspace_id != NEW.workspace_id)\n        ) THEN RAISE(ABORT, 'memory workspace mismatch') END;\n    END",
    "CREATE TRIGGER project_knowledge_heads_workspace_guard_insert\n    BEFORE INSERT ON project_knowledge_heads\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM project_knowledge_revisions r\n            WHERE r.knowledge_revision_id = NEW.current_revision_id\n              AND (r.workspace_id != NEW.workspace_id OR r.knowledge_id != NEW.knowledge_id)\n        ) THEN RAISE(ABORT, 'memory workspace mismatch') END;\n    END",
    "CREATE TRIGGER project_knowledge_heads_workspace_guard_update\n    BEFORE UPDATE OF workspace_id, knowledge_id, current_revision_id ON project_knowledge_heads\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM project_knowledge_revisions r\n            WHERE r.knowledge_revision_id = NEW.current_revision_id\n              AND (r.workspace_id != NEW.workspace_id OR r.knowledge_id != NEW.knowledge_id)\n        ) THEN RAISE(ABORT, 'memory workspace mismatch') END;\n    END",
    "CREATE TRIGGER project_knowledge_revisions_immutable_update\n    BEFORE UPDATE ON project_knowledge_revisions\n    WHEN NEW.knowledge_revision_id IS NOT OLD.knowledge_revision_id\n      OR NEW.knowledge_id IS NOT OLD.knowledge_id\n      OR NEW.workspace_id IS NOT OLD.workspace_id\n      OR NEW.revision IS NOT OLD.revision\n      OR NEW.statement IS NOT OLD.statement\n      OR NEW.statement_digest IS NOT OLD.statement_digest\n      OR NEW.source_candidate_id IS NOT OLD.source_candidate_id\n      OR NEW.source_decision_id IS NOT OLD.source_decision_id\n      OR NEW.supersedes_revision_id IS NOT OLD.supersedes_revision_id\n      OR NEW.sensitivity IS NOT OLD.sensitivity\n      OR NEW.valid_from_unix IS NOT OLD.valid_from_unix\n      OR NEW.valid_until_unix IS NOT OLD.valid_until_unix\n      OR NEW.created_at_unix IS NOT OLD.created_at_unix\n      OR NEW.last_confirmed_at_unix < OLD.last_confirmed_at_unix\n    BEGIN\n        SELECT RAISE(ABORT, 'project knowledge revision is immutable');\n    END",
    "CREATE TRIGGER project_knowledge_revisions_workspace_guard_insert\n    BEFORE INSERT ON project_knowledge_revisions\n    BEGIN\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM project_knowledge_heads h\n            WHERE h.knowledge_id = NEW.knowledge_id\n              AND h.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'memory workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_candidates c\n            WHERE c.candidate_id = NEW.source_candidate_id\n              AND c.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'memory workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_candidate_decisions d\n            WHERE d.decision_id = NEW.source_decision_id\n              AND d.workspace_id != NEW.workspace_id\n        ) THEN RAISE(ABORT, 'memory workspace mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM learning_candidate_decisions d\n            WHERE d.decision_id = NEW.source_decision_id\n              AND NEW.source_candidate_id IS NOT NULL\n              AND d.candidate_id != NEW.source_candidate_id\n        ) THEN RAISE(ABORT, 'memory provenance mismatch') END;\n        SELECT CASE WHEN EXISTS (\n            SELECT 1 FROM project_knowledge_revisions r\n            WHERE r.knowledge_revision_id = NEW.supersedes_revision_id\n              AND (r.workspace_id != NEW.workspace_id OR r.knowledge_id != NEW.knowledge_id)\n        ) THEN RAISE(ABORT, 'memory revision mismatch') END;\n    END",
    "CREATE TRIGGER runtime_control_queue_immutable_identity\n    BEFORE UPDATE OF workspace_id, session_id, position, kind, client_message_id, text,\n                     created_at_unix\n    ON runtime_control_queue\n    BEGIN\n        SELECT RAISE(ABORT, 'runtime control queue identity is immutable');\n    END",
    "CREATE TRIGGER runtime_control_queue_workspace_guard_insert\n    BEFORE INSERT ON runtime_control_queue\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM sessions s\n            WHERE s.session_id = NEW.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'runtime control Session workspace mismatch') END;\n    END",
    "CREATE TRIGGER task_plan_provenance_immutable BEFORE UPDATE ON workflow_task_plan_provenance\n        BEGIN SELECT RAISE(ABORT,'task-plan provenance is immutable'); END",
    "CREATE TRIGGER task_plan_provenance_scope BEFORE INSERT ON workflow_task_plan_provenance BEGIN\n        SELECT CASE\n          WHEN NOT EXISTS(\n            SELECT 1 FROM workflow_revisions r\n            WHERE r.workflow_revision_id=NEW.workflow_revision_id\n              AND r.workspace_id=NEW.workspace_id\n              AND r.revision < 0\n              AND json_extract(r.body_json,'$.parent_workflow_revision_id') IS NULL\n              AND r.workflow_definition_id LIKE 'task_%'\n          ) THEN RAISE(ABORT,'task-plan provenance revision mismatch')\n          WHEN EXISTS(\n            SELECT 1 FROM workflow_definition_heads h\n            JOIN workflow_revisions r\n              ON r.workspace_id=h.workspace_id\n             AND r.workflow_definition_id=h.workflow_definition_id\n            WHERE r.workflow_revision_id=NEW.workflow_revision_id\n          ) THEN RAISE(ABORT,'task-plan revision must not occupy a Definition head')\n          WHEN NOT EXISTS(\n            SELECT 1 FROM workflow_planning_bindings b\n            WHERE b.planning_binding_id=NEW.planning_binding_id\n              AND b.workspace_id=NEW.workspace_id\n          ) THEN RAISE(ABORT,'task-plan provenance binding mismatch')\n          WHEN NOT EXISTS(\n            SELECT 1 FROM workflow_plan_decisions d\n            WHERE d.plan_decision_id=NEW.plan_decision_id\n              AND d.workspace_id=NEW.workspace_id\n          ) THEN RAISE(ABORT,'task-plan provenance decision mismatch')\n        END;\n    END",
    "CREATE TRIGGER task_purpose_immutable BEFORE UPDATE OF purpose ON task_runs\n        BEGIN SELECT RAISE(ABORT, 'Task purpose is immutable'); END",
    "CREATE TRIGGER workflow_agent_run_refs_delete_immutable BEFORE DELETE ON workflow_agent_run_refs\n        BEGIN SELECT RAISE(ABORT, 'Workflow evidence is immutable'); END",
    "CREATE TRIGGER workflow_agent_run_refs_update_immutable BEFORE UPDATE ON workflow_agent_run_refs\n        BEGIN SELECT RAISE(ABORT, 'Workflow evidence is immutable'); END",
    "CREATE TRIGGER workflow_artifact_bindings_delete_immutable BEFORE DELETE ON workflow_artifact_bindings\n        BEGIN SELECT RAISE(ABORT, 'Workflow evidence is immutable'); END",
    "CREATE TRIGGER workflow_artifact_bindings_update_immutable BEFORE UPDATE ON workflow_artifact_bindings\n        BEGIN SELECT RAISE(ABORT, 'Workflow evidence is immutable'); END",
    "CREATE TRIGGER workflow_leaf_ownership_delete_immutable BEFORE DELETE ON workflow_leaf_ownership\n        BEGIN SELECT RAISE(ABORT, 'Workflow evidence is immutable'); END",
    "CREATE TRIGGER workflow_leaf_ownership_update_immutable BEFORE UPDATE ON workflow_leaf_ownership\n        BEGIN SELECT RAISE(ABORT, 'Workflow evidence is immutable'); END",
    "CREATE TRIGGER workflow_node_runs_delete_immutable BEFORE DELETE ON workflow_node_runs\n        BEGIN SELECT RAISE(ABORT, 'Workflow history cannot be deleted'); END",
    "CREATE TRIGGER workflow_node_runs_terminal_immutable BEFORE UPDATE ON workflow_node_runs\n        WHEN OLD.status IN ('completed','failed','cancelled')\n        BEGIN SELECT RAISE(ABORT, 'Terminal Workflow evidence is immutable'); END",
    "CREATE TRIGGER workflow_node_segments_delete_guard\n    BEFORE DELETE ON workflow_node_segments\n    BEGIN SELECT RAISE(ABORT, 'Workflow node segments are append-only'); END",
    "CREATE TRIGGER workflow_node_segments_identity_guard\n    BEFORE UPDATE OF segment_id, workflow_run_id, node_run_id, ordinal, previous_segment_id, created_at_unix\n    ON workflow_node_segments\n    BEGIN SELECT RAISE(ABORT, 'Workflow node segment identity is immutable'); END",
    "CREATE TRIGGER workflow_node_segments_pause_reason_guard\n    BEFORE UPDATE OF status ON workflow_node_segments\n    WHEN NEW.status = 'interrupted' AND NEW.pause_reason IS NULL\n    BEGIN SELECT RAISE(ABORT, 'an interrupted segment records its pause reason'); END",
    "CREATE TRIGGER workflow_node_segments_workspace_guard_insert\n    BEFORE INSERT ON workflow_node_segments\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM workflow_runs r\n            WHERE r.workflow_run_id = NEW.workflow_run_id\n              AND r.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'workflow node segment workspace mismatch') END;\n    END",
    "CREATE TRIGGER workflow_node_steers_workspace_guard_insert\n    BEFORE INSERT ON workflow_node_steers\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM sessions s\n            WHERE s.session_id = NEW.session_id\n              AND s.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'node steer Session workspace mismatch') END;\n    END",
    "CREATE TRIGGER workflow_pause_points_delete_guard\n    BEFORE DELETE ON workflow_pause_points\n    BEGIN SELECT RAISE(ABORT, 'Workflow pause points are immutable evidence'); END",
    "CREATE TRIGGER workflow_pause_points_workspace_guard_insert\n    BEFORE INSERT ON workflow_pause_points\n    WHEN NEW.owner = 'workflow_run'\n    BEGIN\n        SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM workflow_runs r\n            WHERE r.workflow_run_id = NEW.owner_id\n              AND r.workspace_id = NEW.workspace_id\n        ) THEN RAISE(ABORT, 'workflow pause point workspace mismatch') END;\n    END",
